(function(root){'use strict';
const LessonChanges=root.BetlemskaLessonChanges;
// Shared calendar logic; browser copy is generated by tools/embed-data.py.
const nameDays={'Lucie':'12-13','Karel':'11-04','Ondřej':'11-30','Jiří':'04-24','Miriam':'11-05','Zdeněk':'01-23','Vladislav':'01-18','Andrea':'09-26','Jakub':'07-25','Hynek':'02-01','Barbora':'12-04','Pavel':'06-29','Michal':'09-29','Radka':'09-14','Ladislav':'06-27','Martin':'11-11','Lubomír':'06-28','Miloslav':'12-18'};
const labels={narozeniny:'Narozeniny učitelů',pripominka:'Připomenutí předem',akce:'Školní akce',volno:'Volný den',jmeniny:'Svátek učitelů',pisemka:'Písemka 1.A'};
function pragueDay(now=new Date()){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Prague',year:'numeric',month:'2-digit',day:'2-digit'}).format(now)}
function nextDay(date){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10)}
const dateAdd=(date,n)=>{const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const weekday=date=>(new Date(date+'T12:00:00Z').getUTCDay()+6)%7;
const blocked=(date,events)=>weekday(date)>4||events.some(e=>e.date===date&&(e.kind==='volno'||e.allDay===true));
const dateText=date=>new Date(date+'T12:00:00Z').toLocaleDateString('cs-CZ',{timeZone:'UTC',day:'numeric',month:'numeric',year:'numeric'});
function birthdayOn(t,date){return /^\d{4}-\d{2}-\d{2}$/.test(t.birthDate||'')&&t.birthDate.slice(5)===date.slice(5)&&date>=t.birthDate}
function reminderDate(t,date,events=[]){
 const from=t.scheduleValidFrom||'2026-10-12',to=t.scheduleValidTo||'2027-06-30';
 const inTerm=d=>d>=from&&d<=to;
 if(inTerm(date)&&!blocked(date,events)&&(t.schedule||[]).some(l=>l.day===weekday(date)))return date;
 // Use only the supplied school year, allowing its following summer holidays.
 if(date<from||date>dateAdd(to,62))return date;
 for(let n=1;n<=120;n++){const d=dateAdd(date,-n);if(d<from)break;if(!inTerm(d)||blocked(d,events))continue;if((t.schedule||[]).some(l=>l.day===weekday(d)&&(l.classes||[l.cls]).includes('1.A')))return d}
 return date;
}
function celebrationPlans(teachers,events,year){
 const result=[];
 for(const t of teachers){const nameday=nameDays[t.first],birth=t.birthDate?.slice(5);for(const [kind,md]of [['jmeniny',nameday],['narozeniny',birth]]){
  if(!md)continue;const date=year+'-'+md;if(!Number.isFinite(Date.parse(date+'T12:00:00Z'))||new Date(date+'T12:00:00Z').toISOString().slice(0,10)!==date||kind==='narozeniny'&&!birthdayOn(t,date))continue;
  result.push({teacher:t,kind,date,reminderDate:reminderDate(t,date,events),age:kind==='narozeniny'?year-Number(t.birthDate.slice(0,4)):null});
 }}return result;
}
function calendarItems(teachers=[],events=[],exams=[],from='2026-08-01',to='2027-08-31',changes=[]){
 const result=events.map((e,i)=>({...e,id:e.id||'event-'+i}));
 for(const e of exams){if(changes.length&&LessonChanges.suppressesExam(e,teachers,changes))continue;if(events.some(day=>day.date===e.date&&(day.kind==='volno'||day.allDay===true)))continue;result.push({...e,id:'exam-'+e.id,examId:e.id,kind:'pisemka',title:(e.subject?e.subject+' · ':'')+e.title,time:[e.time,e.group?'Skupina '+e.group:''].filter(Boolean).join(' · ')})}
 const first=Number(from.slice(0,4)),last=Math.min(Number(to.slice(0,4)),first+3);
 for(let year=first;year<=last+1;year++){
  const plans=celebrationPlans(teachers,events,year),byDate=new Map();
  for(const plan of plans){const t=plan.teacher,name=t.name||t.first+' '+t.last;
   if(plan.kind==='jmeniny'){if(!byDate.has(plan.date))byDate.set(plan.date,[]);byDate.get(plan.date).push(plan)}
   else result.push({id:'birthday-'+plan.date+'-'+t.id,date:plan.date,title:'Narozeniny · '+name+' · '+plan.age+' let',kind:'narozeniny',time:'Všechno nejlepší!',teacherIds:[t.id],age:plan.age,reminderDate:plan.reminderDate});
   if(plan.reminderDate!==plan.date)result.push({id:'advance-'+plan.kind+'-'+plan.date+'-'+t.id,date:plan.reminderDate,actualDate:plan.date,kind:'pripominka',celebrationKind:plan.kind,title:'Popřej předem · '+name+' bude mít '+(plan.kind==='narozeniny'?'narozeniny':'svátek')+' ('+dateText(plan.date)+')',time:'Poslední předchozí společná výuka podle rozvrhu 1.A.',teacherIds:[t.id],age:plan.age});
  }
  for(const [date,ps] of byDate){const names=xs=>xs.map(p=>p.teacher.name||p.teacher.first+' '+p.teacher.last).join(', '),onDate=ps.filter(p=>p.reminderDate===date);result.push({id:'nameday-'+date,date,title:'Svátek · '+names(ps),kind:'jmeniny',time:'Nezapomeň popřát.',teacherIds:ps.map(p=>p.teacher.id),reminderTeacherIds:onDate.map(p=>p.teacher.id),reminderTitle:'Svátek · '+names(onDate)})}
 }
 return result.filter(e=>e.date>=from&&e.date<=to).sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title,'cs'));
}
function reminderItems(teachers,events,exams,date,changes=[]){return calendarItems(teachers,events,exams,date,date,changes).flatMap(e=>e.kind==='jmeniny'?(e.reminderTeacherIds.length?[{...e,title:e.reminderTitle,teacherIds:e.reminderTeacherIds}]:[]):e.kind==='narozeniny'&&e.reminderDate!==date?[]:[e])}
function reminderKind(e){return ['jmeniny','narozeniny','pripominka'].includes(e.kind)?'namedays':e.kind==='pisemka'?'exams':'events'}
function reminderMessage(items,date,categories){const selected=items.filter(e=>categories[reminderKind(e)]);if(!selected.length)return null;const text=selected.map(e=>e.kind==='jmeniny'?e.title:e.kind==='pisemka'?'Písemka 1.A: '+e.title:e.title+(e.allDay?' (celodenní akce, výuka se nekoná)':'')+(e.time?' ('+e.time+')':''));const body=text.join(' · ');return{id:'tomorrow-'+date,title:'Zítra na Betlémské · '+Number(date.slice(8))+'. '+Number(date.slice(5,7))+'.',body:body.length>320?body.slice(0,317)+'…':body,url:'index.html#events?date='+date,kind:'calendar',count:selected.length}}
const api={nameDays,labels,pragueDay,nextDay,calendarItems,reminderItems,celebrationPlans,reminderDate,birthdayOn,dateText,reminderKind,reminderMessage};


if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.BetlemskaCalendar=api;
})(typeof window!=='undefined'?window:globalThis);
